import { getCityByName, getAttractionsForCity } from "@/lib/data";
import { notFound } from "next/navigation";
import Image from "next/image";
import { PlaceHolderImages } from "@/lib/placeholder-images";
import { type Attraction, type City } from "@/lib/types";
import { Button } from "@/components/ui/button";
import { ArrowLeft } from "lucide-react";
import Link from "next/link";
import { Accordion, AccordionContent, AccordionItem, AccordionTrigger } from "@/components/ui/accordion";
import { Reviews } from "@/components/city/Reviews";

type CityPageProps = {
  params: {
    cityName: string;
  };
};

const getCityData = (cityName: string): { city: City, cityImage: any, attractions: Attraction[] } => {
  const decodedCityName = decodeURIComponent(cityName);
  const city = getCityByName(decodedCityName);

  if (!city) {
    notFound();
  }

  const cityImage = PlaceHolderImages.find((img) => img.id === city!.image);
  const attractions = getAttractionsForCity(city.id);

  return { city, cityImage, attractions };
};

export default async function CityPage({ params }: CityPageProps) {
  const { city, cityImage, attractions } = getCityData(params.cityName);

  return (
    <div className="flex flex-col">
      <section className="relative h-[40vh] w-full flex items-end justify-start text-white p-8">
        {cityImage && (
          <Image
            src={cityImage.imageUrl}
            alt={cityImage.description}
            fill
            className="object-cover"
            priority
            data-ai-hint={cityImage.imageHint}
          />
        )}
        <div className="absolute inset-0 bg-gradient-to-t from-black/70 via-black/40 to-transparent" />
        <div className="relative z-10">
          <h1 className="text-5xl md:text-6xl font-bold font-headline tracking-tight">
            {city.name}
          </h1>
          <p className="max-w-3xl text-lg text-neutral-200 mt-2">
            {city.description}
          </p>
        </div>
      </section>

      <section className="container mx-auto px-4 py-12">
        <Button asChild variant="outline" className="mb-8">
           <Link href="/">
                <ArrowLeft className="mr-2"/> Go Back Home
            </Link>
        </Button>
        
        {attractions.length > 0 ? (
          <Accordion type="single" collapsible className="w-full" defaultValue="item-0">
          {attractions.map((attraction, index) => (
            <AccordionItem key={attraction.id} value={`item-${index}`}>
              <AccordionTrigger className="text-xl font-headline hover:no-underline">
                {attraction.name}
              </AccordionTrigger>
              <AccordionContent>
                <div className="grid md:grid-cols-2 gap-6 items-start">
                    <div>
                        <p className="mb-4 text-muted-foreground">{attraction.description}</p>
                         <Button asChild variant="secondary">
                            <a
                                href={`https://www.google.com/maps/search/?api=1&query=${attraction.latitude},${attraction.longitude}`}
                                target="_blank"
                                rel="noopener noreferrer"
                            >
                                View on Map
                            </a>
                        </Button>
                    </div>
                     <div className="flex flex-col gap-4">
                        {attraction.images.map(imgId => {
                            const img = PlaceHolderImages.find(i => i.id === imgId);
                            return img ? <Image key={img.id} src={img.imageUrl} alt={img.description} width={400} height={300} className="rounded-lg object-cover w-full" data-ai-hint={img.imageHint} /> : null
                        })}
                    </div>
                </div>
                 <Reviews attraction={attraction} />
              </AccordionContent>
            </AccordionItem>
          ))}
        </Accordion>
        ) : (
          <div className="text-center py-16">
            <h2 className="text-2xl font-semibold text-muted-foreground">No attractions found for this city yet.</h2>
            <p className="mt-2 text-muted-foreground">Check back later for updates!</p>
          </div>
        )}

      </section>
    </div>
  );
}
